tool_calls:
mkdir -p /lib /data
cat > /lib/utils.sh <<'EOF'
#!/usr/bin/env bash

# Read stdin and convert to uppercase
to_upper() {
    tr '[:lower:]' '[:upper:]'
}

# Print line count of a file
count_lines() {
    local f="$1"
    [[ -f "$f" ]] || { echo "count_lines: $f: no such file" >&2; return 1; }
    wc -l < "$f" | tr -d ' '
}

# Print byte count of a file
file_size() {
    local f="$1"
    [[ -f "$f" ]] || { echo "file_size: $f: no such file" >&2; return 1; }
    wc -c < "$f" | tr -d ' '
}
EOF
ls -l /data/sample.txt

